referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  let users = clone(d.initial);
  const out = [];
  for (const op of d.operations) {
    if (op.op === "create") users.push(clone(op.user));
    else if (op.op === "update")
      Object.assign(
        users.find((u) => u.id === op.id),
        op.changes,
      );
    else if (op.op === "delete") users = users.filter((u) => u.id !== op.id);
    else
      out.push(
        clone(users.filter((u) => Object.keys(op.where).every((k) => u[k] === op.where[k]))),
      );
  }
  return out;
}

