type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const clone = (v: any): any => JSON.parse(JSON.stringify(v));
  let users = clone(d.initial);
  const out: any[] = [];
  for (const op of d.operations) {
    if (op.op === "create") users.push(clone(op.user));
    else if (op.op === "update")
      Object.assign(
        users.find((u: any) => u.id === op.id),
        op.changes,
      );
    else if (op.op === "delete") users = users.filter((u: any) => u.id !== op.id);
    else
      out.push(
        clone(users.filter((u: any) => Object.keys(op.where).every((k) => u[k] === op.where[k]))),
      );
  }
  return out;
}
